@page "/apply"
@rendermode InteractiveServer
@using sv_2a4fda3864a94d95886327498eda1ac0.Models
@using sv_2a4fda3864a94d95886327498eda1ac0.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@if (_submitted)
{
    <div class="alert alert-success mt-4">
        <h3>Application Submitted Successfully!</h3>
        <p>Your application ID is: <strong>@_applicationId</strong></p>
        <p>Thank you for applying. We will review your application and get back to you.</p>
    </div>
}
else
{
    <!-- Step Indicator Bar -->
    <nav class="step-indicator mb-4">
        <ol class="d-flex list-unstyled justify-content-between">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var isCompleted = stepIndex < _currentStep;
                var isCurrent = stepIndex == _currentStep;
                var isFuture = stepIndex > _currentStep;

                <li class="step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                    @onclick="() => GoToStep(stepIndex)"
                    style="cursor: @(isCompleted ? "pointer" : "default"); flex: 1; text-align: center;">
                    <span class="step-number">
                        @if (isCompleted)
                        {
                            <span>&#10003;</span>
                        }
                        else
                        {
                            @(stepIndex + 1)
                        }
                    </span>
                    <span class="step-label">@_stepNames[stepIndex]</span>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (_currentStep == 0)
    {
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name *</label>
            <input type="text" class="form-control" @bind="_fullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" @bind="_phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address *</label>
            <textarea class="form-control" @bind="_address"></textarea>
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextFromPersonalInfo">Next</button>
        </div>
    }

    <!-- Step 2: Work History -->
    @if (_currentStep == 1)
    {
        <h3>Work History</h3>
        @for (int i = 0; i < _workEntries.Count; i++)
        {
            var index = i;
            <div class="card mb-3 p-3">
                <h5>Position @(index + 1)</h5>
                <div class="mb-2">
                    <label class="form-label">Company *</label>
                    <input type="text" class="form-control" value="@_workEntries[index].Company"
                           @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Company), e.Value?.ToString())" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Job Title *</label>
                    <input type="text" class="form-control" value="@_workEntries[index].Title"
                           @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Title), e.Value?.ToString())" />
                </div>
                <div class="row mb-2">
                    <div class="col-md-4">
                        <label class="form-label">Start Date *</label>
                        <input type="date" class="form-control" value="@_workEntries[index].StartDate?.ToString("yyyy-MM-dd")"
                               @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.StartDate), e.Value?.ToString())" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" disabled="@_workEntries[index].IsCurrent"
                               value="@_workEntries[index].EndDate?.ToString("yyyy-MM-dd")"
                               @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.EndDate), e.Value?.ToString())" />
                    </div>
                    <div class="col-md-4 d-flex align-items-end">
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" checked="@_workEntries[index].IsCurrent"
                                   @onchange="(e) => ToggleCurrentJob(index, (bool)(e.Value ?? false))" />
                            <label class="form-check-label">Currently working here</label>
                        </div>
                    </div>
                </div>
                <div class="mb-2">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" value="@_workEntries[index].Description"
                              @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Description), e.Value?.ToString())"></textarea>
                </div>
                @if (_workEntries.Count > 1)
                {
                    <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                }
            </div>
        }
        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">Add Another Position</button>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
        </div>
    }

    <!-- Step 3: References -->
    @if (_currentStep == 2)
    {
        <h3>References</h3>
        @for (int i = 0; i < _references.Count; i++)
        {
            var index = i;
            <div class="card mb-3 p-3">
                <h5>Reference @(index + 1)</h5>
                <div class="mb-2">
                    <label class="form-label">Name *</label>
                    <input type="text" class="form-control" value="@_references[index].Name"
                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Name), e.Value?.ToString())" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Relationship *</label>
                    <input type="text" class="form-control" value="@_references[index].Relationship"
                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Relationship), e.Value?.ToString())" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Email *</label>
                    <input type="email" class="form-control" value="@_references[index].Email"
                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Email), e.Value?.ToString())" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Phone *</label>
                    <input type="tel" class="form-control" value="@_references[index].Phone"
                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Phone), e.Value?.ToString())" />
                </div>
                @if (_references.Count > 2)
                {
                    <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>
        }
        @if (_references.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">Add Reference</button>
        }
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
        </div>
    }

    <!-- Step 4: Cover Letter -->
    @if (_currentStep == 3)
    {
        <h3>Cover Letter</h3>
        <div class="mb-3">
            <textarea class="form-control" rows="12" maxlength="2000" @bind="_coverLetter"></textarea>
            <small class="text-muted">@(_coverLetter?.Length ?? 0) / 2000 characters</small>
        </div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
        </div>
    }

    <!-- Step 5: Review & Submit -->
    @if (_currentStep == 4)
    {
        <h3>Review & Submit</h3>

        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Personal Information</h5>
                <a href="#" @onclick="() => GoToStep(0)" @onclick:preventDefault>Edit</a>
            </div>
            <dl class="row mb-0">
                <dt class="col-sm-3">Full Name</dt>
                <dd class="col-sm-9">@_fullName</dd>
                <dt class="col-sm-3">Email</dt>
                <dd class="col-sm-9">@_email</dd>
                <dt class="col-sm-3">Phone</dt>
                <dd class="col-sm-9">@_phone</dd>
                <dt class="col-sm-3">Address</dt>
                <dd class="col-sm-9">@_address</dd>
            </dl>
        </div>

        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Work History</h5>
                <a href="#" @onclick="() => GoToStep(1)" @onclick:preventDefault>Edit</a>
            </div>
            @foreach (var entry in _workEntries)
            {
                <div class="mb-2 border-bottom pb-2">
                    <strong>@entry.Title</strong> at @entry.Company<br />
                    <small>@entry.StartDate?.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mt-1 mb-0">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>References</h5>
                <a href="#" @onclick="() => GoToStep(2)" @onclick:preventDefault>Edit</a>
            </div>
            @foreach (var reference in _references)
            {
                <div class="mb-2">
                    <strong>@reference.Name</strong> (@reference.Relationship)<br />
                    <small>@reference.Email | @reference.Phone</small>
                </div>
            }
        </div>

        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Cover Letter</h5>
                <a href="#" @onclick="() => GoToStep(3)" @onclick:preventDefault>Edit</a>
            </div>
            <p style="white-space: pre-wrap;">@_coverLetter</p>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-success" @onclick="SubmitApplication" disabled="@_isSubmitting">
                @if (_isSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Application
            </button>
        </div>
    }
}

<style>
    .step-indicator ol {
        padding: 0;
        margin: 0;
    }
    .step-item {
        padding: 0.5rem;
        border-bottom: 3px solid #dee2e6;
        transition: all 0.2s;
    }
    .step-item.active {
        border-bottom-color: #0d6efd;
        font-weight: bold;
        color: #0d6efd;
    }
    .step-item.completed {
        border-bottom-color: #198754;
        color: #198754;
    }
    .step-item.dimmed {
        color: #adb5bd;
    }
    .step-number {
        display: inline-block;
        width: 1.5rem;
        height: 1.5rem;
        line-height: 1.5rem;
        text-align: center;
        border-radius: 50%;
        margin-right: 0.25rem;
        font-size: 0.85rem;
    }
    .step-item.active .step-number {
        background-color: #0d6efd;
        color: white;
    }
    .step-item.completed .step-number {
        background-color: #198754;
        color: white;
    }
</style>

@code {
    private int _currentStep = 0;
    private bool _submitted = false;
    private bool _isSubmitting = false;
    private int? _applicationId;
    private string? _errorMessage;

    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 state
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _errorMessage = null;
            _currentStep = step;
        }
    }

    private void PreviousStep()
    {
        _errorMessage = null;
        if (_currentStep > 0) _currentStep--;
    }

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        var emailValid = await ApplicationService.ValidateEmailAsync(_email);
        if (!emailValid)
        {
            _errorMessage = "Please enter a valid email address.";
            return;
        }

        _currentStep++;
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = null;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                _errorMessage = "Please fill in company, job title, and start date for all positions.";
                return;
            }
        }

        _currentStep++;
    }

    private void NextFromReferences()
    {
        _errorMessage = null;

        foreach (var reference in _references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                _errorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }

        _currentStep++;
    }

    private void NextFromCoverLetter()
    {
        _errorMessage = null;
        _currentStep++;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = null;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company ?? "", e.Title ?? "", e.StartDate ?? DateTime.MinValue,
                    e.IsCurrent ? null : e.EndDate, e.Description ?? "")).ToList());
            var references = _references.Select(r =>
                new Reference(r.Name ?? "", r.Relationship ?? "", r.Email ?? "", r.Phone ?? "")).ToList();

            var application = new JobApplication(personal, workHistory, references, _coverLetter ?? "");
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    // Work entry helpers
    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());
    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);

    private void UpdateWorkEntry(int index, string field, string? value)
    {
        var entry = _workEntries[index];
        switch (field)
        {
            case nameof(WorkEntryModel.Company): entry.Company = value ?? ""; break;
            case nameof(WorkEntryModel.Title): entry.Title = value ?? ""; break;
            case nameof(WorkEntryModel.StartDate): entry.StartDate = DateTime.TryParse(value, out var sd) ? sd : null; break;
            case nameof(WorkEntryModel.EndDate): entry.EndDate = DateTime.TryParse(value, out var ed) ? ed : null; break;
            case nameof(WorkEntryModel.Description): entry.Description = value ?? ""; break;
        }
    }

    private void ToggleCurrentJob(int index, bool isCurrent)
    {
        _workEntries[index].IsCurrent = isCurrent;
        if (isCurrent) _workEntries[index].EndDate = null;
    }

    // Reference helpers
    private void AddReference() { if (_references.Count < 3) _references.Add(new ReferenceModel()); }
    private void RemoveReference(int index) => _references.RemoveAt(index);

    private void UpdateReference(int index, string field, string? value)
    {
        var reference = _references[index];
        switch (field)
        {
            case nameof(ReferenceModel.Name): reference.Name = value ?? ""; break;
            case nameof(ReferenceModel.Relationship): reference.Relationship = value ?? ""; break;
            case nameof(ReferenceModel.Email): reference.Email = value ?? ""; break;
            case nameof(ReferenceModel.Phone): reference.Phone = value ?? ""; break;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

