        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        var emailValid = await ApplicationService.ValidateEmailAsync(_email);
        if (!emailValid)
        {
            _errorMessage = "Please enter a valid email address.";
            return;
        }

        _currentStep++;
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = null;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                _errorMessage = "Please fill in company, job title, and start date for all positions.";
                return;
            }
        }

        _currentStep++;
    }

